.ds-dashboard { padding-block: var(--space-12) var(--space-16); background: var(--surface-reading); }
.ds-dashboard-header { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-8); padding-bottom: var(--space-8); }
.ds-dashboard-header h1 { font-family: var(--font-source-serif), serif; font-size: 2rem; font-weight: 500; line-height: 1.25; text-wrap: pretty; }
.ds-dashboard-header p { margin-top: var(--space-4); max-width: 60ch; color: var(--text-muted); }
.ds-dashboard-header > a { flex-shrink: 0; }
.ds-dashboard-section { border-top: 1px solid var(--rule-color); padding-block: var(--space-8); min-width: 0; }
.ds-dashboard h2 { font-family: var(--font-source-serif), serif; font-size: 1.5rem; font-weight: 500; line-height: 1.35; margin-bottom: var(--space-4); }
.ds-dashboard h3 { font-family: var(--font-source-serif), serif; font-size: 1.25rem; font-weight: 500; line-height: 1.4; }
.ds-dashboard p { max-width: var(--reading-width); }
.ds-dashboard-link { display: inline-flex; align-items: center; min-height: 44px; color: var(--accent-blue); text-decoration: underline; font-size: 1rem; font-weight: 600; }
.ds-dashboard-link:hover { color: var(--text-ink); background: var(--accent-soft); }
.ds-dashboard-link:active { background: var(--surface-paper); }
.ds-dashboard-overview { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-8); margin-block: var(--space-6); }
.ds-dashboard-overview > div { display: flex; align-items: baseline; gap: var(--space-4); }
.ds-dashboard-overview dt { color: var(--text-muted); font-size: 1rem; }
.ds-dashboard-overview dd { font-size: 1.5rem; font-weight: 600; font-variant-numeric: tabular-nums; }
.ds-dashboard-note, .ds-dashboard-context { color: var(--text-muted); font-size: 1rem; }
.ds-dashboard-note { margin-block: var(--space-2); }
.ds-dashboard-welcome { padding: var(--space-4); margin-top: var(--space-6); background: var(--surface-paper); }
.ds-dashboard-learning { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: var(--space-12); }
.ds-dashboard-lesson { margin-block: var(--space-6) var(--space-3); }
.ds-dashboard-lesson h3 { margin-block: var(--space-2) var(--space-3); }
.ds-dashboard-lesson > a { margin-top: var(--space-3); }
.ds-dashboard-subjects { list-style: none; }
.ds-dashboard-subjects > li { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); gap: var(--space-12); padding-block: var(--space-6); border-bottom: 1px solid var(--rule-color); }
.ds-dashboard-subjects > li:last-child { border-bottom: 0; padding-bottom: 0; }
.ds-dashboard-subject-name { display: flex; align-items: flex-start; gap: var(--space-4); min-width: 0; }
.ds-dashboard-subject-name > svg { flex-shrink: 0; width: 44px; height: 44px; }
.ds-dashboard-subject-name p { font-size: 1rem; color: var(--text-muted); max-width: 42ch; }
.ds-dashboard-subject-progress progress { display: block; width: 100%; max-width: 26rem; height: 0.5rem; margin-block: var(--space-3); appearance: none; border: 0; background: var(--rule-color); color: var(--accent-blue); }
.ds-dashboard-subject-progress progress::-webkit-progress-bar { background: var(--rule-color); }
.ds-dashboard-subject-progress progress::-webkit-progress-value { background: var(--accent-blue); }
.ds-dashboard-subject-progress progress::-moz-progress-bar { background: var(--accent-blue); }
.ds-dashboard-history { margin-top: var(--space-6); }
.ds-dashboard-records { min-width: 0; }
.ds-dashboard-records > p { margin-top: var(--space-3); }
.ds-dashboard-records ul { list-style: none; }
.ds-dashboard-records li { padding-block: var(--space-4); border-bottom: 1px solid var(--rule-color); }
.ds-dashboard-records li > span { margin-top: var(--space-2); font-size: 1rem; }
.ds-dashboard-footer { display: flex; flex-wrap: wrap; gap: var(--space-4) var(--space-8); padding-bottom: 0; }
.ds-dashboard-unavailable { max-width: var(--reading-width); }
.ds-dashboard-unavailable a { margin-top: var(--space-4); margin-right: var(--space-6); }

@media (max-width: 48rem) {
  .ds-dashboard { padding-block: var(--space-8) var(--space-12); }
  .ds-dashboard-header { display: block; }
  .ds-dashboard-header > a { margin-top: var(--space-4); }
  .ds-dashboard-overview { grid-template-columns: minmax(0, 1fr); gap: var(--space-3); }
  .ds-dashboard-overview > div { justify-content: space-between; }
  .ds-dashboard-learning, .ds-dashboard-subjects > li { grid-template-columns: minmax(0, 1fr); gap: var(--space-4); }
  .ds-dashboard-learning > section { padding-block: var(--space-6); }
  .ds-dashboard-subject-progress { padding-left: 60px; }
}
 .ds-dashboard {font-family:var(--font-source-sans),sans-serif;font-size:1.125rem;line-height:1.7;color:var(--text-ink);} .ds-dashboard h1,.ds-dashboard h2,.ds-dashboard h3,.ds-dashboard p,.ds-dashboard ul,.ds-dashboard dl,.ds-dashboard dd{margin:0;} .ds-dashboard h2{margin-bottom:var(--space-4);} .ds-dashboard-header p{margin-top:var(--space-4);} .ds-dashboard-note{margin-block:var(--space-2)!important;} .ds-dashboard-welcome{margin-top:var(--space-6)!important;} .ds-dashboard-overview{margin-block:var(--space-6)!important;} .ds-dashboard-subjects{padding:0;} .ds-dashboard-subject-name>svg{color:var(--accent-blue);} .ds-dashboard-link{text-underline-offset:.22em;text-decoration-thickness:1px;} .ds-dashboard-link:focus-visible{outline:3px solid var(--focus-color);outline-offset:4px;} .ds-dashboard-lesson h3{margin-block:var(--space-2) var(--space-3);}
